// The Japanese "triangle": a word has up to three faces, and each ordered pair
// of faces is a separate skill with its own schedule.

export const FACES = ["kanji", "kana", "meaning"] as const;
export type Face = (typeof FACES)[number];

export const WORD_DIRECTIONS = [
  "kanji>kana", // reading
  "kanji>meaning", // recognition
  "kana>meaning", // comprehension (what you'd hear)
  "meaning>kana", // production (what you'd type)
  "kana>kanji", // writing / IME choice: tracked, not generated by default
  "meaning>kanji", // writing from meaning: tracked, not generated by default
] as const;
export type WordDirection = (typeof WORD_DIRECTIONS)[number];

export const BASIC_DIRECTIONS = ["front>back", "back>front"] as const;
export type BasicDirection = (typeof BASIC_DIRECTIONS)[number];

export type Direction = WordDirection | BasicDirection;
export const ALL_DIRECTIONS: readonly Direction[] = [...WORD_DIRECTIONS, ...BASIC_DIRECTIONS];

export const DEFAULT_WORD_DIRECTIONS: readonly WordDirection[] = [
  "kanji>kana",
  "kanji>meaning",
  "kana>meaning",
  "meaning>kana",
];
export const DEFAULT_BASIC_DIRECTIONS: readonly BasicDirection[] = ["front>back"];

export type NoteType = "word" | "basic";

export interface NoteFaces {
  type: NoteType;
  kanji?: string | null;
  kana?: string | null;
  meaning?: string | null;
  front?: string | null;
  back?: string | null;
}

export function splitDirection(d: Direction): [string, string] {
  const [from, to] = d.split(">");
  return [from!, to!];
}

export function isDirectionForType(d: Direction, type: NoteType): boolean {
  return type === "word"
    ? (WORD_DIRECTIONS as readonly string[]).includes(d)
    : (BASIC_DIRECTIONS as readonly string[]).includes(d);
}

function hasFace(note: NoteFaces, face: string): boolean {
  const v = (note as unknown as Record<string, unknown>)[face];
  return typeof v === "string" && v.trim() !== "";
}

/** A direction is applicable when both of its faces exist on the note. */
export function isApplicable(note: NoteFaces, d: Direction): boolean {
  if (!isDirectionForType(d, note.type)) return false;
  const [from, to] = splitDirection(d);
  return hasFace(note, from) && hasFace(note, to);
}

/**
 * Which directions should have an active card: switched on for the note and
 * applicable to its faces. A kana-only word (さとう) gets kana>meaning and
 * meaning>kana even if the kanji directions are switched on.
 */
export function activeDirections(note: NoteFaces, enabled: readonly Direction[]): Direction[] {
  return enabled.filter((d) => isApplicable(note, d));
}

export interface CardPlan {
  create: Direction[];
  activate: Direction[];
  suspend: Direction[];
}

/**
 * Reconcile existing cards with what the note should have now. Cards are never
 * deleted here: a direction that is switched off, or whose face was removed,
 * is suspended so its review history is kept.
 */
export function planCards(
  note: NoteFaces,
  enabled: readonly Direction[],
  existing: ReadonlyArray<{ direction: Direction; suspended: boolean }>,
): CardPlan {
  const want = new Set(activeDirections(note, enabled));
  const have = new Map(existing.map((c) => [c.direction, c.suspended]));
  const plan: CardPlan = { create: [], activate: [], suspend: [] };
  for (const d of want) {
    if (!have.has(d)) plan.create.push(d);
    else if (have.get(d)) plan.activate.push(d);
  }
  for (const [d, suspended] of have) {
    if (!want.has(d) && !suspended) plan.suspend.push(d);
  }
  return plan;
}

/**
 * Forms a correct answer may take for the face being asked. Japanese IMEs
 * autocomplete kana into kanji, so a typed kanji answer for a "kana" question
 * is accepted too, except when the kanji is what was shown.
 */
export function acceptedAnswers(
  note: NoteFaces & { extra?: Record<string, unknown> | null },
  askFace: string,
  showFace?: string,
): string[] {
  const out: string[] = [];
  const push = (v: unknown) => {
    if (typeof v === "string" && v.trim() !== "" && !out.includes(v)) out.push(v);
    if (Array.isArray(v)) v.forEach(push);
  };
  const n = note as unknown as Record<string, unknown>;
  push(n[askFace]);
  const extra = note.extra ?? {};
  if (askFace === "kana") {
    push(extra.alt_kana);
    if (showFace !== "kanji") {
      push(note.kanji);
      push(extra.alt_kanji);
    }
  } else if (askFace === "kanji") {
    push(extra.alt_kanji);
  } else if (askFace === "meaning") {
    push(extra.alt_meanings);
  }
  return out;
}

export interface DueCardRef {
  card_id: string;
  direction: Direction;
}

export interface Prompt {
  show: string;
  ask: {
    face: string;
    card_id: string;
    direction: Direction;
    accept: string[];
    /**
     * Also correct, but the answer can't be verified: for kanji>kana the shown
     * kanji itself, which an IME produces from the typed reading.
     */
    accept_with_warning?: string[];
  }[];
}

/** Answers to accept with a caveat (see Prompt.accept_with_warning). */
export function acceptedWithWarning(
  note: NoteFaces & { extra?: Record<string, unknown> | null },
  askFace: string,
  showFace: string,
): string[] {
  if (askFace !== "kana" || showFace !== "kanji") return [];
  const out: string[] = [];
  for (const v of [note.kanji, ...(Array.isArray(note.extra?.alt_kanji) ? (note.extra!.alt_kanji as unknown[]) : [])]) {
    if (typeof v === "string" && v.trim() !== "" && !out.includes(v)) out.push(v);
  }
  return out;
}

// When several directions of a note are due, ask the prompt that covers the
// most of them first; ties go by this order (hardest information first).
const SHOW_ORDER = ["kanji", "meaning", "kana", "front", "back"];

/**
 * How many faces one prompt may ask for:
 * - grouped: every face due for the shown face at once (show 犬, expect "いぬ, dog").
 * - same_script: never mix a Japanese answer (kana/kanji) with a meaning answer in one
 *   prompt, so a phone keyboard never has to switch language mid-answer.
 *   Basic notes' front and back count as their own scripts.
 * - single: one card per prompt.
 */
export const ASK_MODES = ["grouped", "same_script", "single"] as const;
export type AskMode = (typeof ASK_MODES)[number];

/** Answer "script": kana and kanji are typed with the Japanese IME, meaning in the learner's language. */
export function answerScript(face: string): string {
  return face === "kana" || face === "kanji" ? "ja" : face;
}

const ASK_ORDER = ["kana", "kanji", "meaning", "back", "front"];

/**
 * Group a note's due cards by the face that is shown. Every card in a group
 * can be asked at once and graded separately. Groups are returned best-first
 * (the shown face covering most due cards first); showing one face may reveal
 * the answers of another, so callers should normally ask only the prompts that
 * share the first prompt's `show` now. With ask_mode same_script or single a
 * group is split into several prompts with the same `show`, asked back-to-back.
 */
export function groupPrompts(
  note: NoteFaces & { extra?: Record<string, unknown> | null },
  due: readonly DueCardRef[],
  mode: AskMode = "grouped",
): Prompt[] {
  const groups = new Map<string, Prompt>();
  for (const c of due) {
    const [from, to] = splitDirection(c.direction);
    let g = groups.get(from);
    if (!g) groups.set(from, (g = { show: from, ask: [] }));
    const warn = acceptedWithWarning(note, to, from);
    g.ask.push({
      face: to,
      card_id: c.card_id,
      direction: c.direction,
      accept: acceptedAnswers(note, to, from),
      ...(warn.length ? { accept_with_warning: warn } : {}),
    });
  }
  const sorted = [...groups.values()].sort(
    (a, b) => b.ask.length - a.ask.length || SHOW_ORDER.indexOf(a.show) - SHOW_ORDER.indexOf(b.show),
  );
  if (mode === "grouped") return sorted;
  const out: Prompt[] = [];
  for (const g of sorted) {
    const ask = [...g.ask].sort((a, b) => ASK_ORDER.indexOf(a.face) - ASK_ORDER.indexOf(b.face));
    const parts = new Map<string, Prompt>();
    for (const a of ask) {
      const key = mode === "single" ? a.card_id : answerScript(a.face);
      let p = parts.get(key);
      if (!p) parts.set(key, (p = { show: g.show, ask: [] }));
      p.ask.push(a);
    }
    out.push(...parts.values());
  }
  return out;
}
